import {ArrowUpRight,ArrowRight,LayoutDashboard,Layers,Users,Bookmark,ScanSearch,FileText,MessageSquare,RefreshCw,Plus,X,Search,Menu,LogOut,ChevronLeft,ChevronRight,Play,Image as ImageIcon,ExternalLink,Check,Pause,Trash2,Edit3,Lock,Activity,Settings,Building2,Mail,Copy} from 'lucide-react';
